class _CameraGridPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = Colors.white.withValues(alpha: 0.1)
      ..strokeWidth = 1
      ..style = PaintingStyle.stroke;

    final spacing = size.width / 3;

    // Rule of thirds grid
    for (int i = 1; i < 3; i++) {
      final x = i * spacing;
      canvas.drawLine(
          Offset(x, 0),
          Offset(x, size.height),
          Paint()
            ..color = Colors.white12
            ..strokeWidth = 0.5);
    }

    for (int i = 1; i < 3; i++) {
      final y = i * size.height / 3;
      canvas.drawLine(
          Offset(0, y),
          Offset(size.width, y),
          Paint()
            ..color = Colors.white12
            ..strokeWidth = 0.5);
    }

    // Center crosshair
    final crosshairPaint = Paint()
      ..color = Colors.white.withValues(alpha: 0.3)
      ..strokeWidth = 1
      ..style = PaintingStyle.stroke;

    final centerX = size.width / 2;
    final centerY = size.height / 2;
    const crossSize = 30.0;

    canvas.drawLine(
      Offset(centerX - crossSize, centerY),
      Offset(centerX + crossSize, centerY),
      crosshairPaint,
    );
    canvas.drawLine(
      Offset(centerX, centerY - crossSize),
      Offset(centerX, centerY + crossSize),
      crosshairPaint,
    );

    // Center circle
    canvas.drawCircle(
      Offset(size.width / 2, size.height / 2),
      30,
      Paint()
        ..color = Colors.transparent
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1
        ..color = Colors.white30,
    );
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

final chatMessagesProvider = StateNotifierProvider<ChatMessagesNotifier, List<ChatMessage>>((ref) {
  return ChatMessagesNotifier(ref);
});

class ChatMessage {
  final String text;
  final bool isUser;
  final String time;
  final bool isStreaming;
  final bool isVoice;

  ChatMessage({
    required this.text,
    required this.isUser,
    required this.time,
    this.isStreaming = false,
    this.isVoice = false,
  });

  ChatMessage copyWith({
    String? text,
    bool? isStreaming,
    bool? isVoice,
  }) {
    return ChatMessage(
      text: text ?? this.text,
      isUser: isUser,
      time: time,
      isStreaming: isStreaming ?? this.isStreaming,
      isVoice: isVoice ?? this.isVoice,
    );
  }
}

class ChatMessagesNotifier extends StateNotifier<List<ChatMessage>> {
  final Ref ref;

  ChatMessagesNotifier(this.ref) : super([
    ChatMessage(
      text: 'Hello! How can I help you today?',
      isUser: false,
      time: _formatTime(DateTime.now()),
    ),
  ]);

  static String _formatTime(DateTime dt) {
    return '${dt.hour.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')}';
  }

  void sendMessage(String text) {
    if (text.trim().isEmpty) return;

    final userMessage = ChatMessage(
      text: text.trim(),
      isUser: true,
      time: _formatTime(DateTime.now()),
    );
    state = [...state, userMessage];

    // Add a streaming assistant message
    final assistantMessage = ChatMessage(
      text: '',
      isUser: false,
      time: _formatTime(DateTime.now()),
      isStreaming: true,
    );
    state = [...state, assistantMessage];

    _streamChatResponse(text.trim());
  }

  void _streamChatResponse(String message) async {
    final apiService = ref.read(apiServiceProvider);
    final activityNotifier = ref.read(activityStreamProvider.notifier);
    int messageIndex = state.length - 1;

    try {
      // First, start an agent run to get a task ID for detailed activity streaming
      final runResult = await apiService.runAgent(message);
      final taskId = runResult.taskId;
      
      // Start the task stream for live activity
      activityNotifier.startStream(taskId);
      
      // Also stream the chat response for the text
      await for (final chunk in apiService.chatStream(message)) {
        if (chunk.error != null) {
          state = [
            ...state.sublist(0, messageIndex),
            state[messageIndex].copyWith(
              text: 'Error: ${chunk.error}',
              isStreaming: false,
            ),
          ];
          break;
        }

        if (chunk.delta != null && chunk.delta!.isNotEmpty) {
          final currentText = state[messageIndex].text;
          state = [
            ...state.sublist(0, messageIndex),
            state[messageIndex].copyWith(text: currentText + chunk.delta!),
          ];
        }

        if (chunk.done == true) {
          state = [
            ...state.sublist(0, messageIndex),
            state[messageIndex].copyWith(isStreaming: false),
          ];
          break;
        }
      }
    } catch (e) {
      state = [
        ...state.sublist(0, messageIndex),
        state[messageIndex].copyWith(
          text: 'Error: $e',
          isStreaming: false,
        ),
      ];
    }
  }
}

// Activity Stream Events for Live Activity Panel
class ActivityEvent {
  final String type;
  final String message;
  final String? detail;
  final DateTime timestamp;
  final bool isComplete;
  final bool isError;

  ActivityEvent({
    required this.type,
    required this.message,
    this.detail,
    required this.timestamp,
    this.isComplete = false,
    this.isError = false,
  });

  factory ActivityEvent.fromTaskStreamEvent(TaskStreamEvent event) {
    String type = event.type;
    String message = '';
    String? detail;
    bool isComplete = false;
    bool isError = false;

    switch (type) {
      case 'planning_started':
        message = '🧠 Thinking...';
        break;
      case 'plan_created':
        message = '🧠 Plan created';
        detail = 'Executing plan...';
        isComplete = true;
        break;
      case 'step_started':
        message = '⚙️ Running workflow';
        detail = 'Step ${event.currentStep}: ${event.stepName ?? event.stepDescription ?? ''}';
        break;
      case 'step_completed':
        message = '✅ Step completed';
        detail = event.stepName ?? event.stepDescription;
        isComplete = true;
        break;
      case 'step_failed':
        message = '❌ Step failed';
        detail = event.error;
        isError = true;
        break;
      case 'tool_call_started':
        message = '🔧 Using tool';
        detail = event.toolName;
        break;
      case 'tool_call_completed':
        message = '🔧 Tool completed';
        detail = event.toolName;
        isComplete = true;
        break;
      case 'tool_call_failed':
        message = '🔧 Tool failed';
        detail = event.toolName;
        isError = true;
        break;
      case 'llm_stream_start':
        message = '🤖 Generating response...';
        break;
      case 'llm_token':
        message = '🤖 Generating...';
        detail = event.llmToken;
        break;
      case 'llm_stream_end':
        message = '🤖 Response generated';
        isComplete = true;
        break;
      case 'verification_started':
        message = '🔍 Verifying...';
        break;
      case 'verification_completed':
        message = '🔍 Verification passed';
        isComplete = true;
        break;
      case 'agent_task_assigned':
        message = '👤 Agent working';
        detail = event.agentName;
        break;
      case 'agent_task_completed':
        message = '👤 Agent completed';
        detail = event.agentName;
        isComplete = true;
        break;
      case 'memory_consolidated':
        message = '📂 Memory updated';
        break;
      case 'skill_acquired':
        message = '🎓 Skill learned';
        detail = event.skillName;
        break;
      case 'confidence_update':
        message = '📊 Confidence updated';
        detail = '${(event.confidence ?? 0 * 100).toStringAsFixed(0)}%';
        break;
      case 'replan_triggered':
        message = '🔄 Replanning...';
        break;
      case 'task_completed':
        message = '✅ Task completed';
        isComplete = true;
        break;
      case 'task_failed':
        message = '❌ Task failed';
        detail = event.error;
        isError = true;
        break;
      case 'connected':
        message = '🔗 Connected to task stream';
        break;
      case 'learning_started':
        message = '📚 Learn & Complete: Starting...';
        break;
      case 'skill_found':
        message = '🎓 Found relevant skill';
        detail = event.detail;
        isComplete = true;
        break;
      case 'researching':
        message = '🔍 Researching best approach...';
        break;
      case 'research_done':
        message = '🔍 Research complete';
        detail = event.detail;
        isComplete = true;
        break;
      case 'sandbox_test':
        message = '🧪 Testing in sandbox...';
        break;
      case 'sandbox_test_done':
        message = event.isError ? '🧪 Sandbox test failed' : '🧪 Sandbox test passed';
        detail = event.detail;
        isComplete = true;
        isError = event.isError;
        break;
      case 'learning_executing':
        message = '⚡ Executing with learned approach...';
        break;
      case 'skill_acquired':
        message = '🎓 Skill acquired & saved';
        detail = event.skillName;
        isComplete = true;
        break;
      case 'learn_failed':
        message = '❌ Could not complete after attempts';
        detail = event.detail;
        isError = true;
        break;
      default:
        message = '⚙️ ${type.replaceAll('_', ' ')}';
    }

    return ActivityEvent(
      type: type,
      message: message,
      detail: detail,
      timestamp: DateTime.now(),
      isComplete: isComplete,
      isError: isError,
    );
  }
}

// Activity Stream Notifier
class ActivityStreamNotifier extends StateNotifier<List<ActivityEvent>> {
  final Ref ref;
  StreamSubscription? _subscription;

  ActivityStreamNotifier(this.ref) : super([]);

  void startStream(String taskId) {
    // Clear previous activities
    state = [];

    final apiService = ref.read(apiServiceProvider);
    _subscription = apiService.taskStream(taskId).listen(
      (event) {
        final activity = ActivityEvent.fromTaskStreamEvent(event);
        state = [...state, activity];
      },
      onError: (error) {
        state = [...state, ActivityEvent(
          type: 'error',
          message: '❌ Stream error',
          detail: error.toString(),
          timestamp: DateTime.now(),
          isError: true,
        )];
      },
      onDone: () {
        // Stream completed
      },
    );
  }

  void clear() {
    state = [];
    _subscription?.cancel();
    _subscription = null;
  }

  @override
  void dispose() {
    _subscription?.cancel();
    super.dispose();
  }
}

// Provider for Activity Stream
final activityStreamProvider = StateNotifierProvider<ActivityStreamNotifier, List<ActivityEvent>>((ref) {
  return ActivityStreamNotifier(ref);
});

class _HealthProbesWidget extends ConsumerWidget {
  const _HealthProbesWidget();

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final healthAsync = ref.watch(extHealthProvider);

    return healthAsync.when(
      data: (health) {
        final isHealthy = health.healthy;
        final statusColor = isHealthy ? MayaTheme.neonEmerald : MayaTheme.error;
        final statusText = isHealthy ? 'Healthy' : (health.message ?? 'Unhealthy');
        return Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
          decoration: BoxDecoration(
            color: statusColor.withValues(alpha: 0.15),
            borderRadius: BorderRadius.circular(12),
            border: Border.all(
              color: statusColor.withValues(alpha: 0.5),
              width: 1,
            ),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                isHealthy ? Icons.check_circle : Icons.error,
                size: 14,
                color: statusColor,
              ),
              const SizedBox(width: 4),
              Text(
                statusText,
                style: MayaTheme.labelSmall.copyWith(
                  color: statusColor,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ],
          ),
        );
      },
      loading: () => Container(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
        decoration: BoxDecoration(
          color: MayaTheme.glassWhite10,
          borderRadius: BorderRadius.circular(12),
          border: Border.all(color: MayaTheme.glassWhite30),
        ),
        child: const SizedBox(
          width: 16,
          height: 16,
          child: CircularProgressIndicator(
            strokeWidth: 2,
