class _ChatScreen extends ConsumerStatefulWidget {
  const _ChatScreen();

  @override
  ConsumerState<_ChatScreen> createState() => _ChatScreenState();
}

class _ChatScreenState extends ConsumerState<_ChatScreen> {
  final textController = TextEditingController();
  final scaffoldKey = GlobalKey<ScaffoldState>();

  void handleSend() {
    final text = textController.text.trim();
    if (text.isNotEmpty) {
      textController.clear();
      ref.read(chatMessagesProvider.notifier).sendMessage(text);
    }
  }

  @override
  void dispose() {
    textController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final messages = ref.watch(chatMessagesProvider);
    final activities = ref.watch(activityStreamProvider);
    final hasActivities = activities.isNotEmpty;

    return SafeArea(
      child: Scaffold(
        key: scaffoldKey,
        backgroundColor: Colors.transparent,
        drawer: _AppDrawer(),
        body: Column(
          children: [
            // Header
            Container(
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(
                border: Border(
                  bottom: BorderSide(
                      color: MayaTheme.neonCyan.withValues(alpha: 0.1)),
                ),
              ),
              child: Row(
                children: [
                  IconButton(
                    icon: const Icon(Icons.menu_rounded),
                    onPressed: () => scaffoldKey.currentState?.openDrawer(),
                    style: IconButton.styleFrom(
                        backgroundColor: MayaTheme.glassWhite10),
                  ),
                  const Text('Chat', style: MayaTheme.headlineLarge),
                  const Spacer(),
                  if (hasActivities)
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                      decoration: BoxDecoration(
                        color: MayaTheme.neonOrange.withValues(alpha: 0.2),
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(color: MayaTheme.neonOrange.withValues(alpha: 0.5)),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          const SizedBox(
                            width: 10,
                            height: 10,
                            child: CircularProgressIndicator(
                              strokeWidth: 2,
                              valueColor: AlwaysStoppedAnimation(MayaTheme.neonOrange),
                            ),
                          ),
                          const SizedBox(width: 6),
                          Text(
                            'Live Activity',
                            style: MayaTheme.labelSmall.copyWith(color: MayaTheme.neonOrange),
                          ),
                        ],
                      ),
                    ),
                ],
              ),
            ),

            // Live Activity Panel
            if (hasActivities)
              _ActivityPanel(activities: activities),

            // Messages
            Expanded(
              child: ListView.builder(
                padding: const EdgeInsets.all(16),
                reverse: true,
                itemCount: messages.length,
                itemBuilder: (context, index) {
                  final message = messages[messages.length - 1 - index];
                  return _ChatBubble(
                    text: message.text,
                    isUser: message.isUser,
                    time: message.time,
                    isStreaming: message.isStreaming,
                    isVoice: message.isVoice ?? false,
                  ).animate().fadeIn(delay: (index * 50).ms).slideY(begin: 0.2);
                },
              ),
            ),

            // Input
            Container(
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(
                border: Border(
                  top: BorderSide(
                      color: MayaTheme.neonCyan.withValues(alpha: 0.1)),
                ),
              ),
              child: Row(
                children: [
                  Expanded(
                    child: Container(
                      margin: const EdgeInsets.symmetric(horizontal: 8),
                      padding: const EdgeInsets.symmetric(horizontal: 16),
                      decoration: BoxDecoration(
                        color: MayaTheme.slate700,
                        borderRadius: BorderRadius.circular(24),
                        border: Border.all(
                            color: MayaTheme.neonCyan.withValues(alpha: 0.2)),
                      ),
                      child: TextField(
                        controller: textController,
                        decoration: InputDecoration(
                          hintText: 'Message Maya...',
                          hintStyle: MayaTheme.bodyMedium
                              .copyWith(color: Colors.white38),
                          border: InputBorder.none,
                          contentPadding: EdgeInsets.zero,
                        ),
                        style: MayaTheme.bodyMedium,
                        maxLines: null,
                        onSubmitted: (value) {
                          if (value.trim().isNotEmpty) {
                            ref.read(chatMessagesProvider.notifier).sendMessage(value);
                          }
                        },
                      ),
                    ),
                  ),
                  IconButton(
                    icon: const Icon(Icons.send_rounded,
                        color: MayaTheme.neonCyan),
                    onPressed: handleSend,
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

