                          const SizedBox(width: 12),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  agentName.isNotEmpty ? agentName : 'Unassigned',
                                  style: MayaTheme.titleSmall,
