  void showMoveMouseDialog(BuildContext context, Future<void> Function(String, Map<String, dynamic>) onSendCommand) {
    final xController = TextEditingController();
    final yController = TextEditingController();
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        backgroundColor: MayaTheme.slate800,
        title: const Text('Move Mouse', style: MayaTheme.headlineSmall),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextField(
              controller: xController,
              keyboardType: TextInputType.number,
              style: MayaTheme.bodyMedium,
              decoration: InputDecoration(
                labelText: 'X',
                labelStyle: MayaTheme.bodyMedium.copyWith(color: Colors.white54),
                filled: true,
                fillColor: MayaTheme.slate700,
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide.none),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: yController,
              keyboardType: TextInputType.number,
              style: MayaTheme.bodyMedium,
              decoration: InputDecoration(
                labelText: 'Y',
                labelStyle: MayaTheme.bodyMedium.copyWith(color: Colors.white54),
                filled: true,
                fillColor: MayaTheme.slate700,
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide.none),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')),
          ElevatedButton(
            onPressed: () {
              final x = int.tryParse(xController.text);
              final y = int.tryParse(yController.text);
              if (x != null && y != null) {
                Navigator.pop(context);
                onSendCommand('move_mouse', {'x': x, 'y': y});
              }
            },
            style: ElevatedButton.styleFrom(backgroundColor: MayaTheme.neonCyan),
            child: const Text('Move'),
          ),
        ],
      ),
    );
  }

  void showClickDialog(BuildContext context, Future<void> Function(String, Map<String, dynamic>) onSendCommand) {
    final xController = TextEditingController();
    final yController = TextEditingController();
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        backgroundColor: MayaTheme.slate800,
        title: const Text('Click', style: MayaTheme.headlineSmall),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextField(
              controller: xController,
              keyboardType: TextInputType.number,
              style: MayaTheme.bodyMedium,
              decoration: InputDecoration(
                labelText: 'X (optional)',
                labelStyle: MayaTheme.bodyMedium.copyWith(color: Colors.white54),
                filled: true,
                fillColor: MayaTheme.slate700,
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide.none),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: yController,
              keyboardType: TextInputType.number,
              style: MayaTheme.bodyMedium,
              decoration: InputDecoration(
                labelText: 'Y (optional)',
                labelStyle: MayaTheme.bodyMedium.copyWith(color: Colors.white54),
                filled: true,
                fillColor: MayaTheme.slate700,
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide.none),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')),
          ElevatedButton(
            onPressed: () {
              final params = <String, dynamic>{};
              final x = int.tryParse(xController.text);
              final y = int.tryParse(yController.text);
              if (x != null) params['x'] = x;
              if (y != null) params['y'] = y;
              Navigator.pop(context);
              onSendCommand('click', params);
            },
            style: ElevatedButton.styleFrom(backgroundColor: MayaTheme.neonCyan),
            child: const Text('Click'),
          ),
        ],
      ),
    );
  }

  void showTypeTextDialog(BuildContext context, Future<void> Function(String, Map<String, dynamic>) onSendCommand) {
    final controller = TextEditingController();
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
