                          _ConfigRow(label: 'Port', value: config.port.toString()),
                          _ConfigRow(label: 'User', value: config.user.isNotEmpty ? config.user : 'Not set'),
                          _ConfigRow(label: 'SSH Key', value: config.hasKey ? 'Configured' : 'Not set'),
