class _IntervalSlider extends ConsumerStatefulWidget {
  @override
  ConsumerState<_IntervalSlider> createState() => _IntervalSliderState();
}

class _IntervalSliderState extends ConsumerState<_IntervalSlider> {
  double _interval = 30.0;

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Slider(
          value: _interval,
          min: 5,
          max: 300,
          divisions: 59,
          label: '\${_interval.toInt()}s',
          activeColor: MayaTheme.neonCyan,
          inactiveColor: Colors.white24,
          onChanged: (v) => setState(() => _interval = v),
        ),
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            Text('\${_interval.toInt()}s', style: MayaTheme.bodyMedium.copyWith(color: MayaTheme.neonCyan)),
            ElevatedButton.icon(
              onPressed: () async {
                final apiService = ref.read(apiServiceProvider);
                try {
                  await apiService.startUnifiedLoop(interval: _interval);
                  if (mounted) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(content: Text('Loop started (\${_interval.toInt()}s interval)'), backgroundColor: MayaTheme.neonEmerald),
                    );
                    ref.invalidate(unifiedLoopStatusProvider);
                  }
                } catch (e) {
                  if (mounted) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(content: Text('Failed to start: \$e'), backgroundColor: MayaTheme.error),
                    );
                  }
                }
              },
              icon: const Icon(Icons.play_arrow_rounded),
              label: const Text('Start Loop'),
              style: ElevatedButton.styleFrom(
                backgroundColor: MayaTheme.neonEmerald,
                foregroundColor: Colors.black,
              ),
            ),
          ],
        ),
      ],
    );
  }
}

class _LoopControlButtons extends ConsumerWidget {
  final String currentState;

  const _LoopControlButtons({required this.currentState});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final isRunning = currentState == 'running';
    final isPaused = currentState == 'paused';
    final isStopped = currentState == 'stopped';

    return Column(
      children: [
        Row(
          children: [
            Expanded(
              child: ElevatedButton.icon(
                onPressed: isRunning || isPaused ? null : () async {
                  final apiService = ref.read(apiServiceProvider);
                  try {
                    await apiService.startUnifiedLoop();
                    if (mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('Loop started'), backgroundColor: MayaTheme.neonEmerald),
                      );
                      ref.invalidate(unifiedLoopStatusProvider);
                    }
                  } catch (e) {
                    if (mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('Failed to start: \$e'), backgroundColor: MayaTheme.error),
                      );
                    }
                  }
                },
                icon: const Icon(Icons.play_arrow_rounded),
                label: const Text('Start'),
                style: ElevatedButton.styleFrom(
                  backgroundColor: MayaTheme.neonEmerald,
                  foregroundColor: Colors.black,
                  padding: const EdgeInsets.symmetric(vertical: 14),
                ),
              ),
            ),
            const SizedBox(width: 12),
            Expanded(
              child: ElevatedButton.icon(
                onPressed: isRunning ? () async {
                  final apiService = ref.read(apiServiceProvider);
                  try {
                    await apiService.pauseUnifiedLoop();
                    if (mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('Loop paused'), backgroundColor: MayaTheme.neonOrange),
                      );
                      ref.invalidate(unifiedLoopStatusProvider);
                    }
                  } catch (e) {
                    if (mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('Failed to pause: \$e'), backgroundColor: MayaTheme.error),
                      );
                    }
                  }
                } : null,
                icon: const Icon(Icons.pause_rounded),
                label: const Text('Pause'),
                style: ElevatedButton.styleFrom(
                  backgroundColor: MayaTheme.neonOrange,
                  foregroundColor: Colors.black,
                  padding: const EdgeInsets.symmetric(vertical: 14),
                ),
              ),
            ),
          ],
        ),
        const SizedBox(height: 12),
        Row(
          children: [
            Expanded(
              child: ElevatedButton.icon(
                onPressed: isPaused ? () async {
                  final apiService = ref.read(apiServiceProvider);
                  try {
                    await apiService.resumeUnifiedLoop();
                    if (mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('Loop resumed'), backgroundColor: MayaTheme.neonEmerald),
                      );
                      ref.invalidate(unifiedLoopStatusProvider);
                    }
                  } catch (e) {
                    if (mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('Failed to resume: \$e'), backgroundColor: MayaTheme.error),
                      );
                    }
                  }
                } : null,
                icon: const Icon(Icons.play_circle_rounded),
                label: const Text('Resume'),
                style: ElevatedButton.styleFrom(
                  backgroundColor: MayaTheme.neonEmerald,
                  foregroundColor: Colors.black,
                  padding: const EdgeInsets.symmetric(vertical: 14),
                ),
              ),
            ),
            const SizedBox(width: 12),
            Expanded(
              child: ElevatedButton.icon(
                onPressed: isRunning || isPaused ? () async {
                  final apiService = ref.read(apiServiceProvider);
                  try {
                    await apiService.stopUnifiedLoop();
                    if (mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('Loop stopped'), backgroundColor: MayaTheme.error),
                      );
                      ref.invalidate(unifiedLoopStatusProvider);
                    }
                  } catch (e) {
                    if (mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('Failed to stop: \$e'), backgroundColor: MayaTheme.error),
                      );
                    }
                  }
                } : null,
                icon: const Icon(Icons.stop_rounded),
                label: const Text('Stop'),
                style: ElevatedButton.styleFrom(
                  backgroundColor: MayaTheme.error,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(vertical: 14),
                ),
              ),
            ),
          ],
        ),
      ],
    );
  }
}

// Persistent Goal Pursuit Screen (Phase 35)
class _PersistentGoalsScreen extends ConsumerStatefulWidget {
  const _PersistentGoalsScreen();

  @override
  ConsumerState<_PersistentGoalsScreen> createState() => _PersistentGoalsScreenState();
}

class _PersistentGoalsScreenState extends ConsumerState<_PersistentGoalsScreen>
    with SingleTickerProviderStateMixin {
  late TabController _tabController;
  Timer? _refreshTimer;

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 4, vsync: this);
    _refreshTimer = Timer.periodic(const Duration(seconds: 10), (_) {
      if (mounted) {
        ref.invalidate(incompleteGoalsProvider);
        ref.invalidate(goalsListProvider(null));
      }
    });
  }

  @override
  void dispose() {
    _tabController.dispose();
    _refreshTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      child: Scaffold(
        backgroundColor: MayaTheme.slate900,
        appBar: AppBar(
          title: const Text('Persistent Goal Pursuit', style: MayaTheme.headlineSmall),
          backgroundColor: MayaTheme.slate900,
          elevation: 0,
          leading: IconButton(
            icon: const Icon(Icons.arrow_back_rounded),
            onPressed: () => Navigator.pop(context),
          ),
          actions: [
            IconButton(
              icon: const Icon(Icons.refresh_rounded),
              onPressed: () {
                ref.invalidate(incompleteGoalsProvider);
                ref.invalidate(goalsListProvider(null));
              },
            ),
            IconButton(
              icon: const Icon(Icons.add_rounded),
              onPressed: () => _showCreateGoalDialog(context),
            ),
          ],
          bottom: TabBar(
            controller: _tabController,
            indicatorColor: MayaTheme.neonCyan,
            labelColor: MayaTheme.neonCyan,
            unselectedLabelColor: Colors.white54,
            isScrollable: true,
            tabs: const [
              Tab(icon: Icons.flag_rounded, text: 'Incomplete'),
              Tab(icon: Icons.list_alt_rounded, text: 'All Goals'),
              Tab(icon: Icons.add_task_rounded, text: 'Create Goal'),
              Tab(icon: Icons.analytics_rounded, text: 'Stats'),
            ],
          ),
        ),
        body: TabBarView(
          controller: _tabController,
          children: [
            _IncompleteGoalsTab(),
            _AllGoalsTab(),
            _CreateGoalTab(),
            _GoalsStatsTab(),
          ],
        ),
      ),
    );
  }

  void _showCreateGoalDialog(BuildContext context) {
    _tabController.animateTo(2);
  }
}

class _IncompleteGoalsTab extends ConsumerWidget {
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final incompleteAsync = ref.watch(incompleteGoalsProvider);

    return incompleteAsync.when(
      data: (data) => data.goals.isEmpty
          ? _emptyState('No Incomplete Goals', 'All goals are completed or abandoned', Icons.flag_rounded)
          : SingleChildScrollView(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text('Incomplete Goals', style: MayaTheme.titleLarge),
                  const SizedBox(height: 8),
                  Text(
                    'Goals that survived a restart but were never finished. Prioritized by priority.',
                    style: MayaTheme.bodyMedium.copyWith(color: Colors.white54),
                  ),
                  const SizedBox(height: 16),
                  ListView.separated(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: data.goals.length,
                    separatorBuilder: (_, __) => const SizedBox(height: 8),
                    itemBuilder: (_, index) {
                      final goal = data.goals[index];
                      return _GoalCard(
                        goal: goal,
                        onTap: () => _showGoalDetail(context, ref, goal.id),
                        onResume: () => _resumeGoal(context, ref, goal.id),
                        onPause: () => _pauseGoal(context, ref, goal.id),
                        onCancel: () => _cancelGoal(context, ref, goal.id),
                      );
                    },
                  ),
                ],
              ),
            ),
      loading: () => const Center(child: CircularProgressIndicator(valueColor: AlwaysStoppedAnimation(MayaTheme.neonCyan))),
      error: (err, _) => Center(child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
        const Icon(Icons.error_rounded, size: 48, color: MayaTheme.error),
        const SizedBox(height: 16),
        Text('Error loading incomplete goals', style: MayaTheme.bodyMedium.copyWith(color: MayaTheme.error)),
        const SizedBox(height: 8),
        Text(err.toString(), style: MayaTheme.bodySmall.copyWith(color: Colors.white38)),
      ])),
    );
  }

  void _showGoalDetail(BuildContext context, WidgetRef ref, String goalId) {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _GoalDetailSheet(goalId: goalId),
    );
  }

  Future<void> _resumeGoal(BuildContext context, WidgetRef ref, String goalId) async {
    final apiService = ref.read(apiServiceProvider);
    try {
      final result = await apiService.resumeGoal(goalId: goalId, execute: false);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(result.success ? 'Goal resumed (propose-only)' : 'Failed: ${result.error}'),
            backgroundColor: result.success ? MayaTheme.neonEmerald : MayaTheme.error,
          ),
        );
        ref.invalidate(incompleteGoalsProvider);
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Resume failed: $e'), backgroundColor: MayaTheme.error),
        );
      }
    }
  }

  Future<void> _pauseGoal(BuildContext context, WidgetRef ref, String goalId) async {
    final apiService = ref.read(apiServiceProvider);
    try {
      await apiService.updateGoal(goalId: goalId, updates: {'status': 'suspended'});
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Goal paused'), backgroundColor: MayaTheme.neonOrange),
        );
        ref.invalidate(incompleteGoalsProvider);
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Pause failed: $e'), backgroundColor: MayaTheme.error),
        );
      }
    }
  }

  Future<void> _cancelGoal(BuildContext context, WidgetRef ref, String goalId) async {
    final apiService = ref.read(apiServiceProvider);
    try {
      await apiService.updateGoal(goalId: goalId, updates: {'status': 'abandoned'});
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Goal cancelled'), backgroundColor: MayaTheme.error),
        );
        ref.invalidate(incompleteGoalsProvider);
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Cancel failed: $e'), backgroundColor: MayaTheme.error),
        );
      }
    }
  }
}

