                if (goal.status == 'active' || goal.status == 'suspended' || goal.status == 'blocked') ...[
                  TextButton.icon(
                    onPressed: onResume,
                    icon: const Icon(Icons.play_arrow_rounded, size: 18),
                    label: const Text('Resume'),
                    style: TextButton.styleFrom(foregroundColor: MayaTheme.neonEmerald),
