// Knowledge Engine Screen (Phase 36)
class _KnowledgeEngineScreen extends ConsumerStatefulWidget {
  const _KnowledgeEngineScreen();

  @override
  ConsumerState<_KnowledgeEngineScreen> createState() => _KnowledgeEngineScreenState();
}

class _KnowledgeEngineScreenState extends ConsumerState<_KnowledgeEngineScreen>
    with SingleTickerProviderStateMixin {
  late TabController _tabController;
  Timer? _refreshTimer;

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 4, vsync: this);
    _refreshTimer = Timer.periodic(const Duration(seconds: 15), (_) {
      if (mounted) {
        ref.invalidate(knowledgeStatsProvider);
      }
    });
  }

  @override
  void dispose() {
    _tabController.dispose();
    _refreshTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      child: Scaffold(
        backgroundColor: MayaTheme.slate900,
        appBar: AppBar(
          title: const Text('Knowledge Engine', style: MayaTheme.headlineSmall),
          backgroundColor: MayaTheme.slate900,
          elevation: 0,
          leading: IconButton(
            icon: const Icon(Icons.arrow_back_rounded),
            onPressed: () => Navigator.pop(context),
          ),
          actions: [
            IconButton(
              icon: const Icon(Icons.refresh_rounded),
              onPressed: () {
                ref.invalidate(knowledgeStatsProvider);
              },
            ),
          ],
          bottom: TabBar(
            controller: _tabController,
            indicatorColor: MayaTheme.neonCyan,
            labelColor: MayaTheme.neonCyan,
            unselectedLabelColor: Colors.white54,
            isScrollable: true,
            tabs: const [
              Tab(icon: Icon(Icons.search_rounded), text: 'Query Knowledge'),
              Tab(icon: Icon(Icons.lightbulb_rounded), text: 'Learn / Teach'),
              Tab(icon: Icon(Icons.psychology_rounded), text: 'Beliefs'),
              Tab(icon: Icon(Icons.analytics_rounded), text: 'Stats'),
            ],
          ),
        ),
        body: TabBarView(
          controller: _tabController,
          children: [
            _KnowledgeQueryTab(),
            _KnowledgeLearnTab(),
            _BeliefsTab(),
            _KnowledgeStatsTab(),
          ],
        ),
      ),
    );
  }
}

class _KnowledgeQueryTab extends ConsumerStatefulWidget {
  @override
  ConsumerState<_KnowledgeQueryTab> createState() => _KnowledgeQueryTabState();
}

class _KnowledgeQueryTabState extends ConsumerState<_KnowledgeQueryTab> {
  final _queryController = TextEditingController();
  final _domainController = TextEditingController();
  int _limit = 10;
  KnowledgeQueryResponse? _lastResult;
  bool _isQuerying = false;

  @override
  void dispose() {
    _queryController.dispose();
    _domainController.dispose();
    super.dispose();
  }

  Future<void> _runQuery() async {
    if (_queryController.text.trim().isEmpty) return;

    setState(() => _isQuerying = true);
    try {
      final apiService = ref.read(apiServiceProvider);
      final result = await apiService.queryKnowledge(
        query: _queryController.text.trim(),
        domain: _domainController.text.trim().isEmpty ? null : _domainController.text.trim(),
        limit: _limit,
      );
      setState(() {
        _lastResult = result;
        _isQuerying = false;
      });
    } catch (e) {
      setState(() => _isQuerying = false);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Query failed: $e'), backgroundColor: MayaTheme.error),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Query Knowledge Base', style: MayaTheme.titleLarge),
          const SizedBox(height: 8),
          Text(
            'Search Maya\'s structured knowledge base using semantic similarity.',
            style: MayaTheme.bodyMedium.copyWith(color: Colors.white54),
          ),
          const SizedBox(height: 24),
          // Query Form
          Container(
            padding: const EdgeInsets.all(16),
            decoration: MayaTheme.glassCard(),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                TextField(
                  controller: _queryController,
                  style: const TextStyle(color: Colors.white),
                  maxLines: 3,
                  decoration: InputDecoration(
                    labelText: 'Query *',
                    hintText: 'e.g., What is the VPS SSH port?',
                    labelStyle: const TextStyle(color: Colors.white54),
                    alignLabelWithHint: true,
                    prefixIcon: const Padding(
                      padding: EdgeInsets.only(bottom: 40),
                      child: Icon(Icons.search_rounded, color: Colors.white54),
                    ),
                    enabledBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                      borderSide: const BorderSide(color: Colors.white24),
                    ),
                    focusedBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                      borderSide: const BorderSide(color: MayaTheme.neonCyan),
                    ),
                    filled: true,
                    fillColor: MayaTheme.slate800,
                  ),
                ),
                const SizedBox(height: 16),
                TextField(
                  controller: _domainController,
                  style: const TextStyle(color: Colors.white),
                  decoration: InputDecoration(
                    labelText: 'Domain Filter (optional)',
                    hintText: 'e.g., general, vps, deployment',
                    labelStyle: const TextStyle(color: Colors.white54),
                    prefixIcon: const Icon(Icons.category_rounded, color: Colors.white54),
                    enabledBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                      borderSide: const BorderSide(color: Colors.white24),
                    ),
                    focusedBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                      borderSide: const BorderSide(color: MayaTheme.neonCyan),
                    ),
                    filled: true,
                    fillColor: MayaTheme.slate800,
                  ),
                ),
                const SizedBox(height: 16),
                Row(
                  children: [
                    Text('Limit: $_limit', style: MayaTheme.bodyMedium.copyWith(color: MayaTheme.neonCyan)),
                    Expanded(child: Slider(
                      value: _limit.toDouble(),
                      min: 1,
                      max: 25,
                      divisions: 24,
                      activeColor: MayaTheme.neonCyan,
                      inactiveColor: Colors.white24,
                      onChanged: (v) => setState(() => _limit = v.toInt()),
                    )),
                  ],
                ),
                const SizedBox(height: 16),
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton.icon(
                    onPressed: _isQuerying ? null : _runQuery,
                    icon: _isQuerying
                        ? const SizedBox(
                            width: 20, height: 20,
                            child: CircularProgressIndicator(strokeWidth: 2, valueColor: AlwaysStoppedAnimation(Colors.white)),
                          )
                        : const Icon(Icons.search_rounded),
                    label: Text(_isQuerying ? 'Querying...' : 'Run Query'),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: MayaTheme.neonCyan,
                      foregroundColor: Colors.black,
                      padding: const EdgeInsets.symmetric(vertical: 14),
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                    ),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 24),
          // Results
          if (_lastResult != null) ...[
            const Text('Results', style: MayaTheme.titleLarge),
            const SizedBox(height: 12),
            _lastResult!.results.isEmpty
                ? Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(32),
                    decoration: MayaTheme.glassCard(),
                    child: const Center(child: Text('No results found', style: MayaTheme.bodyMedium)),
                  )
                : ListView.separated(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: _lastResult!.results.length,
                    separatorBuilder: (_, __) => const SizedBox(height: 12),
                    itemBuilder: (_, index) {
                      final item = _lastResult!.results[index];
                      return _KnowledgeResultCard(item: item, rank: index + 1);
                    },
                  ),
          ],
        ],
      ),
    );
  }
}

