class _BeliefsTabState extends ConsumerState<_BeliefsTab> {
  final _domainController = TextEditingController();
  double _minConfidence = 0.0;
  BeliefsQueryResponse? _lastResult;

  @override
  void dispose() {
    _domainController.dispose();
    super.dispose();
  }

  Future<void> _queryBeliefs() async {
    try {
      final apiService = ref.read(apiServiceProvider);
      final result = await apiService.queryBeliefs(
        domain: _domainController.text.trim().isEmpty ? null : _domainController.text.trim(),
        minConfidence: _minConfidence,
      );
      setState(() => _lastResult = result);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Query failed: $e'), backgroundColor: MayaTheme.error),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Beliefs', style: MayaTheme.titleLarge),
          const SizedBox(height: 8),
          Text(
            'Query Maya\'s beliefs. Beliefs are individual propositions with confidence levels and domains.',
            style: MayaTheme.bodyMedium.copyWith(color: Colors.white54),
          ),
          const SizedBox(height: 24),
          // Query Form
          Container(
            padding: const EdgeInsets.all(16),
            decoration: MayaTheme.glassCard(),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                TextField(
                  controller: _domainController,
                  style: const TextStyle(color: Colors.white),
                  decoration: InputDecoration(
                    labelText: 'Domain Filter (optional)',
                    hintText: 'e.g., general, vps, coding',
                    labelStyle: const TextStyle(color: Colors.white54),
                    prefixIcon: const Icon(Icons.category_rounded, color: Colors.white54),
                    enabledBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                      borderSide: const BorderSide(color: Colors.white24),
                    ),
                    focusedBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                      borderSide: const BorderSide(color: MayaTheme.neonCyan),
                    ),
                    filled: true,
                    fillColor: MayaTheme.slate800,
                  ),
                ),
                const SizedBox(height: 16),
                Row(
                  children: [
                    Text('Min Confidence: ${(_minConfidence * 100).toStringAsFixed(0)}%', style: MayaTheme.bodyMedium.copyWith(color: MayaTheme.neonCyan)),
                    Expanded(child: Slider(
                      value: _minConfidence,
                      min: 0.0,
                      max: 1.0,
                      divisions: 20,
                      activeColor: MayaTheme.neonCyan,
                      inactiveColor: Colors.white24,
                      onChanged: (v) => setState(() => _minConfidence = v),
                    )),
                  ],
                ),
                const SizedBox(height: 16),
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton.icon(
                    onPressed: _queryBeliefs,
                    icon: const Icon(Icons.psychology_rounded),
                    label: const Text('Query Beliefs'),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: MayaTheme.neonViolet,
                      foregroundColor: Colors.white,
                      padding: const EdgeInsets.symmetric(vertical: 14),
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                    ),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 24),
          // Results
          if (_lastResult != null) ...[
            const Text('Beliefs', style: MayaTheme.titleLarge),
            const SizedBox(height: 12),
            _lastResult!.beliefs.isEmpty
                ? Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(32),
                    decoration: MayaTheme.glassCard(),
                    child: const Center(child: Text('No beliefs found', style: MayaTheme.bodyMedium)),
                  )
                : ListView.separated(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: _lastResult!.beliefs.length,
                    separatorBuilder: (_, __) => const SizedBox(height: 8),
                    itemBuilder: (_, index) {
                      final belief = _lastResult!.beliefs[index];
                      return _BeliefCard(belief: belief);
                    },
                  ),
          ],
        ],
      ),
    );
  }
}

class _BeliefCard extends StatelessWidget {
  final Belief belief;

  const _BeliefCard({required this.belief});

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: MayaTheme.glassCard(),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: _getConfidenceColor(belief.confidence).withValues(alpha: 0.2),
                  borderRadius: BorderRadius.circular(10),
                ),
                child: Icon(Icons.psychology_rounded, color: _getConfidenceColor(belief.confidence), size: 24),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(belief.proposition, style: MayaTheme.bodyLarge),
                    const SizedBox(height: 4),
                    Wrap(
                      spacing: 8,
                      children: [
                        Chip(
                          label: Text(belief.domain, style: MayaTheme.labelSmall),
                          backgroundColor: MayaTheme.neonViolet.withValues(alpha: 0.2),
                          side: const BorderSide(color: MayaTheme.neonViolet),
                        ),
                        Chip(
                          label: Text(belief.source, style: MayaTheme.labelSmall),
                          backgroundColor: MayaTheme.neonEmerald.withValues(alpha: 0.2),
                          side: const BorderSide(color: MayaTheme.neonEmerald),
                        ),
                        Chip(
                          label: Text('${(belief.confidence * 100).toStringAsFixed(0)}%', style: MayaTheme.labelSmall),
                          backgroundColor: _getConfidenceColor(belief.confidence).withValues(alpha: 0.2),
                          side: BorderSide(color: _getConfidenceColor(belief.confidence)),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            ],
          ),
          if (belief.evidence != null && belief.evidence!.isNotEmpty) ...[
            const SizedBox(height: 12),
            const Text('Evidence:', style: MayaTheme.labelMedium),
            const SizedBox(height: 4),
            Wrap(
              spacing: 4,
              children: belief.evidence!.map((e) => Chip(
                label: Text(e, style: MayaTheme.bodySmall),
                backgroundColor: MayaTheme.slate800,
                side: const BorderSide(color: Colors.white12),
              )).toList(),
            ),
          ],
        ],
      ),
    );
  }

  Color _getConfidenceColor(double confidence) {
    if (confidence >= 0.8) return MayaTheme.neonEmerald;
    if (confidence >= 0.5) return MayaTheme.neonCyan;
    if (confidence >= 0.3) return MayaTheme.neonOrange;
    return MayaTheme.error;
  }
}

