// Skill Generalization Screen (Phase 37)
class _SkillGeneralizationScreen extends ConsumerStatefulWidget {
  const _SkillGeneralizationScreen();

  @override
  ConsumerState<_SkillGeneralizationScreen> createState() => _SkillGeneralizationScreenState();
}

class _SkillGeneralizationScreenState extends ConsumerState<_SkillGeneralizationScreen>
    with SingleTickerProviderStateMixin {
  late TabController _tabController;
  Timer? _refreshTimer;

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 3, vsync: this);
    _refreshTimer = Timer.periodic(const Duration(seconds: 15), (_) {
      if (mounted) {
        ref.invalidate(proceduralListProvider);
        ref.invalidate(proceduralStatsProvider);
      }
    });
  }

  @override
  void dispose() {
    _tabController.dispose();
    _refreshTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      child: Scaffold(
        backgroundColor: MayaTheme.slate900,
        appBar: AppBar(
          title: const Text('Skill Generalization', style: MayaTheme.headlineSmall),
          backgroundColor: MayaTheme.slate900,
          elevation: 0,
          leading: IconButton(
            icon: const Icon(Icons.arrow_back_rounded),
            onPressed: () => Navigator.pop(context),
          ),
          actions: [
            IconButton(
              icon: const Icon(Icons.refresh_rounded),
              onPressed: () {
                ref.invalidate(proceduralListProvider);
                ref.invalidate(proceduralStatsProvider);
              },
            ),
          ],
          bottom: TabBar(
            controller: _tabController,
            indicatorColor: MayaTheme.neonCyan,
            labelColor: MayaTheme.neonCyan,
            unselectedLabelColor: Colors.white54,
            tabs: const [
              Tab(icon: Icon(Icons.search_rounded), text: 'Search Skills'),
              Tab(icon: Icon(Icons.auto_awesome_rounded), text: 'Compose Skills'),
              Tab(icon: Icon(Icons.list_alt_rounded), text: 'All Skills'),
            ],
          ),
        ),
        body: TabBarView(
          controller: _tabController,
          children: [
            _SkillSearchTab(),
            _SkillComposeTab(),
            _AllSkillsTab(),
          ],
        ),
      ),
    );
  }
}

class _SkillSearchTab extends ConsumerStatefulWidget {
  @override
  ConsumerState<_SkillSearchTab> createState() => _SkillSearchTabState();
}

class _SkillSearchTabState extends ConsumerState<_SkillSearchTab> {
  final _queryController = TextEditingController();
  int _limit = 10;
  ProceduralSearchResponse? _lastResult;
  bool _isSearching = false;

  @override
  void dispose() {
    _queryController.dispose();
    super.dispose();
  }

  Future<void> _searchSkills() async {
    if (_queryController.text.trim().isEmpty) return;

    setState(() => _isSearching = true);
    try {
      final apiService = ref.read(apiServiceProvider);
      final result = await apiService.searchProcedural(
        query: _queryController.text.trim(),
        limit: _limit,
      );
      setState(() {
        _lastResult = result;
        _isSearching = false;
      });
    } catch (e) {
      setState(() => _isSearching = false);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Search failed: $e'), backgroundColor: MayaTheme.error),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Search Skills', style: MayaTheme.titleLarge),
          const SizedBox(height: 8),
          Text(
            'Find relevant skills for a goal using semantic search. Skills generalize to novel-but-similar tasks.',
            style: MayaTheme.bodyMedium.copyWith(color: Colors.white54),
          ),
          const SizedBox(height: 24),
          // Search Form
          Container(
            padding: const EdgeInsets.all(16),
            decoration: MayaTheme.glassCard(),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                TextField(
                  controller: _queryController,
                  style: const TextStyle(color: Colors.white),
                  maxLines: 3,
                  decoration: InputDecoration(
                    labelText: 'Goal / Task Description *',
                    hintText: 'e.g., Build a REST API with authentication',
                    labelStyle: const TextStyle(color: Colors.white54),
                    alignLabelWithHint: true,
                    prefixIcon: const Padding(
                      padding: EdgeInsets.only(bottom: 40),
                      child: Icon(Icons.search_rounded, color: Colors.white54),
                    ),
                    enabledBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                      borderSide: const BorderSide(color: Colors.white24),
                    ),
                    focusedBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                      borderSide: const BorderSide(color: MayaTheme.neonCyan),
                    ),
                    filled: true,
                    fillColor: MayaTheme.slate800,
                  ),
                ),
                const SizedBox(height: 16),
                Row(
                  children: [
                    Text('Max Results: $_limit', style: MayaTheme.bodyMedium.copyWith(color: MayaTheme.neonCyan)),
                    Expanded(child: Slider(
                      value: _limit.toDouble(),
                      min: 1,
                      max: 25,
                      divisions: 24,
                      activeColor: MayaTheme.neonCyan,
                      inactiveColor: Colors.white24,
                      onChanged: (v) => setState(() => _limit = v.toInt()),
                    )),
                  ],
                ),
                const SizedBox(height: 16),
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton.icon(
                    onPressed: _isSearching ? null : _searchSkills,
                    icon: _isSearching
                        ? const SizedBox(
                            width: 20, height: 20,
                            child: CircularProgressIndicator(strokeWidth: 2, valueColor: AlwaysStoppedAnimation(Colors.white)),
                          )
                        : const Icon(Icons.search_rounded),
                    label: Text(_isSearching ? 'Searching...' : 'Search Skills'),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: MayaTheme.neonCyan,
                      foregroundColor: Colors.black,
                      padding: const EdgeInsets.symmetric(vertical: 14),
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                    ),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 24),
          // Results
          if (_lastResult != null) ...[
            const Text('Matching Skills', style: MayaTheme.titleLarge),
            const SizedBox(height: 12),
            _lastResult!.skills.isEmpty
                ? Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(32),
                    decoration: MayaTheme.glassCard(),
                    child: const Center(child: Text('No matching skills found', style: MayaTheme.bodyMedium)),
                  )
                : ListView.separated(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: _lastResult!.skills.length,
                    separatorBuilder: (_, __) => const SizedBox(height: 12),
                    itemBuilder: (_, index) {
                      final skill = _lastResult!.skills[index];
                      return _SkillResultCard(skill: skill, rank: index + 1);
                    },
                  ),
          ],
        ],
      ),
    );
  }
}

