// Semantic Index / Vector Retrieval Screen (Phase 40)
class _SemanticIndexScreen extends ConsumerStatefulWidget {
  const _SemanticIndexScreen();

  @override
  ConsumerState<_SemanticIndexScreen> createState() => _SemanticIndexScreenState();
}

class _SemanticIndexScreenState extends ConsumerState<_SemanticIndexScreen>
    with SingleTickerProviderStateMixin {
  late TabController _tabController;
  Timer? _refreshTimer;

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 3, vsync: this);
    _refreshTimer = Timer.periodic(const Duration(seconds: 30), (_) {
      if (mounted) {
        ref.invalidate(vectorSearchStatsProvider);
      }
    });
  }

  @override
  void dispose() {
    _tabController.dispose();
    _refreshTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      child: Scaffold(
        backgroundColor: MayaTheme.slate900,
        appBar: AppBar(
          title: const Text('Semantic Index', style: MayaTheme.headlineSmall),
          backgroundColor: MayaTheme.slate900,
          elevation: 0,
          leading: IconButton(
            icon: const Icon(Icons.arrow_back_rounded),
            onPressed: () => Navigator.pop(context),
          ),
          actions: [
            IconButton(
              icon: const Icon(Icons.refresh_rounded),
              onPressed: () {
                ref.invalidate(vectorSearchStatsProvider);
              },
            ),
          ],
          bottom: TabBar(
            controller: _tabController,
            indicatorColor: MayaTheme.neonCyan,
            labelColor: MayaTheme.neonCyan,
            unselectedLabelColor: Colors.white54,
            tabs: const [
              Tab(icon: Icon(Icons.data_array_rounded), text: 'Vector Store'),
              Tab(icon: Icon(Icons.search_rounded), text: 'Search'),
              Tab(icon: Icon(Icons.settings_rounded), text: 'Config'),
            ],
          ),
        ),
        body: TabBarView(
          controller: _tabController,
          children: [
            _VectorStoreTab(),
            _VectorSearchTab(),
            _VectorConfigTab(),
          ],
        ),
      ),
    );
  }
}

