class _ResumeNowForm extends ConsumerStatefulWidget {
  @override
  ConsumerState<_ResumeNowForm> createState() => _ResumeNowFormState();
}

class _ResumeNowFormState extends ConsumerState<_ResumeNowForm> {
  bool _execute = false;
  int _maxGoals = 5;
  bool _planProposals = true;
  bool _isResuming = false;
  AutoResumeResponse? _lastResult;

  Future<void> _resumeGoals() async {
    setState(() => _isResuming = true);
    try {
      final apiService = ref.read(apiServiceProvider);
      final result = await apiService.resumeIncompleteGoals(
        execute: _execute,
        maxGoals: _maxGoals,
        planProposals: _planProposals,
      );
      setState(() {
        _lastResult = result;
        _isResuming = false;
      });
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Resumed ${result.results.length} goals (${result.results.where((r) => r.success).length} succeeded)'),
            backgroundColor: MayaTheme.neonEmerald,
          ),
        );
      }
    } catch (e) {
      setState(() => _isResuming = false);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Resume failed: $e'), backgroundColor: MayaTheme.error),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: MayaTheme.glassCard(),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Execution Mode', style: MayaTheme.titleMedium),
          const SizedBox(height: 12),
          SwitchListTile(
            title: const Text('Execute (not just propose)', style: MayaTheme.bodyMedium),
            subtitle: Text('When ON, actually re-executes ACTIVE goals through the gated pipeline. Requires RBAC execute.', style: MayaTheme.bodySmall.copyWith(color: Colors.white54)),
            value: _execute,
            onChanged: (v) => setState(() => _execute = v),
            activeThumbColor: MayaTheme.neonEmerald,
          ),
          const Divider(color: Colors.white12),
          SwitchListTile(
            title: const Text('Plan Proposals', style: MayaTheme.bodyMedium),
            subtitle: Text('When OFF, performs cheap policy scan without LLM calls (scan-only mode).', style: MayaTheme.bodySmall.copyWith(color: Colors.white54)),
            value: _planProposals,
            onChanged: (v) => setState(() => _planProposals = v),
            activeThumbColor: MayaTheme.neonCyan,
          ),
          const Divider(color: Colors.white12),
          Row(
            children: [
              Text('Max Goals: $_maxGoals', style: MayaTheme.bodyMedium.copyWith(color: MayaTheme.neonCyan)),
              Expanded(child: Slider(
                value: _maxGoals.toDouble(),
                min: 1,
                max: 50,
                divisions: 49,
                activeColor: MayaTheme.neonCyan,
                inactiveColor: Colors.white24,
                onChanged: (v) => setState(() => _maxGoals = v.toInt()),
              )),
            ],
          ),
          const SizedBox(height: 16),
          SizedBox(
            width: double.infinity,
            child: ElevatedButton.icon(
              onPressed: _isResuming ? null : _resumeGoals,
              icon: _isResuming
                  ? const SizedBox(
                      width: 20, height: 20,
                      child: CircularProgressIndicator(strokeWidth: 2, valueColor: AlwaysStoppedAnimation(Colors.white)),
                    )
                  : const Icon(Icons.replay_rounded),
              label: Text(_isResuming ? 'Resuming...' : 'Resume Goals Now'),
              style: ElevatedButton.styleFrom(
                backgroundColor: MayaTheme.neonViolet,
                foregroundColor: Colors.white,
                padding: const EdgeInsets.symmetric(vertical: 14),
                shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
              ),
            ),
          ),
          if (_lastResult != null) ...[
            const SizedBox(height: 16),
            const Text('Last Result', style: MayaTheme.titleMedium),
            const SizedBox(height: 12),
            ListView.separated(
              shrinkWrap: true,
              physics: const NeverScrollableScrollPhysics(),
              itemCount: _lastResult!.results.length,
              separatorBuilder: (_, __) => const SizedBox(height: 8),
              itemBuilder: (_, index) {
                final r = _lastResult!.results[index];
                return _AutoResumeResultCard(result: r);
              },
            ),
          ],
        ],
      ),
    );
  }
}

