class _IncompleteGoalsPreview extends ConsumerWidget {
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final incompleteAsync = ref.watch(incompleteGoalsProvider);

    return incompleteAsync.when(
      data: (data) => data.goals.isEmpty
          ? Container(
              width: double.infinity,
              padding: const EdgeInsets.all(32),
              decoration: MayaTheme.glassCard(),
              child: const Center(child: Text('No incomplete goals found', style: MayaTheme.bodyMedium)),
            )
          : ListView.separated(
              shrinkWrap: true,
              physics: const NeverScrollableScrollPhysics(),
              itemCount: data.goals.length > 10 ? 10 : data.goals.length,
              separatorBuilder: (_, __) => const SizedBox(height: 8),
              itemBuilder: (_, index) {
                final goal = data.goals[index];
                return Container(
                  padding: const EdgeInsets.all(12),
                  decoration: MayaTheme.glassCard(),
                  child: Row(
                    children: [
                      Container(
                        padding: const EdgeInsets.all(8),
                        decoration: BoxDecoration(
                          color: _getStatusColor(goal.status).withValues(alpha: 0.2),
                          borderRadius: BorderRadius.circular(8),
                        ),
                        child: Icon(Icons.flag_rounded, color: _getStatusColor(goal.status), size: 20),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(goal.description, style: MayaTheme.bodyMedium, maxLines: 1, overflow: TextOverflow.ellipsis),
                            Text('${goal.status.toUpperCase()} • Priority: ${goal.priority.toInt()}', style: MayaTheme.bodySmall.copyWith(color: Colors.white54)),
                          ],
                        ),
                      ),
                    ],
                  ),
                );
              },
            ),
      loading: () => const Center(child: CircularProgressIndicator(valueColor: AlwaysStoppedAnimation(MayaTheme.neonCyan))),
      error: (err, _) => Text('Error: $err', style: MayaTheme.bodyMedium.copyWith(color: MayaTheme.error)),
    );
  }

  Color _getStatusColor(String status) {
    switch (status.toLowerCase()) {
      case 'active': return MayaTheme.neonEmerald;
      case 'suspended': return MayaTheme.neonOrange;
      case 'blocked': return MayaTheme.error;
      default: return Colors.white54;
    }
  }
}

