  @override
  Widget build(BuildContext context) {
    return SafeArea(child: Scaffold(backgroundColor: MayaTheme.slate900, appBar: AppBar(title: const Text('Vision AI', style: MayaTheme.headlineSmall), backgroundColor: MayaTheme.slate900, elevation: 0, leading: IconButton(icon: const Icon(Icons.arrow_back_rounded), onPressed: () => Navigator.pop(context)), actions: [IconButton(icon: const Icon(Icons.refresh_rounded), onPressed: () { ref.invalidate(visionStatsProvider); })], bottom: TabBar(controller: _tabController, indicatorColor: MayaTheme.neonCyan, labelColor: MayaTheme.neonCyan, unselectedLabelColor: Colors.white54, tabs: const [Tab(icon: Icon(Icons.image_rounded), text: 'Analyze'), Tab(icon: Icon(Icons.text_fields_rounded), text: 'OCR')],)), body: TabBarView(controller: _tabController, children: [_VisionAnalyzeTab(), _VisionOCRTab()],));
  }
}

class _VisionAnalyzeTab extends ConsumerStatefulWidget { @override ConsumerState<_VisionAnalyzeTab> createState() => _VisionAnalyzeTabState(); }
class _VisionAnalyzeTabState extends ConsumerState<_VisionAnalyzeTab> {
  final _imagePathController = TextEditingController();
  VisionAnalyzeResponse? _lastResult;
  bool _isAnalyzing = false;

  @override void dispose() { _imagePathController.dispose(); super.dispose(); }

  Future<void> _analyze() async {
    if (_imagePathController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Image path or URL required'), backgroundColor: MayaTheme.error));
      return;
    }
    setState(() => _isAnalyzing = true);
    try {
      final apiService = ref.read(apiServiceProvider);
      final result = await apiService.analyzeVision({'image_path': _imagePathController.text.trim()});
      setState(() { _lastResult = result; _isAnalyzing = false; });
    } catch (e) { setState(() => _isAnalyzing = false); if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Failed: $e'), backgroundColor: MayaTheme.error)); }
  }

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Image Analysis', style: MayaTheme.titleLarge),
          const SizedBox(height: 8),
          Text('Analyze an image using AI vision', style: MayaTheme.bodyMedium.copyWith(color: Colors.white54)),
          const SizedBox(height: 24),
          Container(
            padding: const EdgeInsets.all(16),
            decoration: MayaTheme.glassCard(),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                TextField(
                  controller: _imagePathController,
                  style: const TextStyle(color: Colors.white),
                  decoration: InputDecoration(
                    labelText: 'Image Path/URL *',
                    hintText: '/path/to/image.jpg or https://example.com/image.png',
                    labelStyle: const TextStyle(color: Colors.white54),
                    prefixIcon: const Icon(Icons.image_rounded, color: Colors.white54),
                    enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: const BorderSide(color: Colors.white24)),
                    focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: const BorderSide(color: MayaTheme.neonCyan)),
                    filled: true,
                    fillColor: MayaTheme.slate800,
                  ),
                ),
                const SizedBox(height: 24),
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton.icon(
                    onPressed: _isAnalyzing ? null : _analyze,
                    icon: _isAnalyzing
                        ? const SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2, valueColor: AlwaysStoppedAnimation(Colors.white)))
                        : const Icon(Icons.search_rounded),
                    label: Text(_isAnalyzing ? 'Analyzing...' : 'Analyze Image'),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: MayaTheme.neonCyan,
                      foregroundColor: Colors.black,
                      padding: const EdgeInsets.symmetric(vertical: 14),
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                    ),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 24),
          if (_lastResult != null) ...[
            const Text('Analysis Result', style: MayaTheme.titleLarge),
            const SizedBox(height: 12),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(color: MayaTheme.slate800, borderRadius: BorderRadius.circular(8), border: Border.all(color: Colors.white12)),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text('Description', style: MayaTheme.titleMedium),
                  const SizedBox(height: 8),
                  Text(_lastResult!.description, style: MayaTheme.bodyMedium),
                  const SizedBox(height: 16),
                  const Text('Objects Detected', style: MayaTheme.titleMedium),
                  const SizedBox(height: 8),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children: _lastResult!.objects.map((o) => Chip(label: Text(o, style: MayaTheme.bodySmall), backgroundColor: MayaTheme.slate800, side: const BorderSide(color: Colors.white12))).toList(),
                  ),
                  const SizedBox(height: 16),
                  const Text('Text Extracted', style: MayaTheme.titleMedium),
                  const SizedBox(height: 8),
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(color: MayaTheme.slate800, borderRadius: BorderRadius.circular(8), border: Border.all(color: Colors.white12)),
                    child: SelectableText(_lastResult!.text.isNotEmpty ? _lastResult!.text.toString() : 'No text detected', style: MayaTheme.bodySmall.copyWith(fontFamily: 'monospace')),
                  ),
                ],
              ),
            ),
          ],
        ],
      ),
    );
  }
}

class _VisionOCRTab extends ConsumerStatefulWidget { @override ConsumerState<_VisionOCRTab> createState() => _VisionOCRTabState(); }
class _VisionOCRTabState extends ConsumerState<_VisionOCRTab> {
  final _imagePathController = TextEditingController();
  VisionOCRResponse? _lastResult;
  bool _isProcessing = false;
  String? _error;

  @override void dispose() { _imagePathController.dispose(); super.dispose(); }

  Future<void> _ocr() async {
    if (_imagePathController.text.trim().isEmpty) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Image path or URL required'), backgroundColor: MayaTheme.error)); return; }
    setState(() { _isProcessing = true; _error = null; });
    try {
      final apiService = ref.read(apiServiceProvider);
      final result = await apiService.ocrVision({'image_path': _imagePathController.text.trim()});
      setState(() { _lastResult = result; _isProcessing = false; });
    } catch (e) {
      setState(() { _isProcessing = false; _error = e.toString(); });
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Failed: $e'), backgroundColor: MayaTheme.error));
    }
  }

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('OCR (Text Extraction)', style: MayaTheme.titleLarge),
          const SizedBox(height: 8),
          Text('Extract text from an image', style: MayaTheme.bodyMedium.copyWith(color: Colors.white54)),
          const SizedBox(height: 24),
          Container(
            padding: const EdgeInsets.all(16),
            decoration: MayaTheme.glassCard(),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                TextField(
                  controller: _imagePathController,
                  style: const TextStyle(color: Colors.white),
                  decoration: InputDecoration(
                    labelText: 'Image Path/URL *',
                    hintText: '/path/to/image.jpg or https://example.com/image.png',
                    labelStyle: const TextStyle(color: Colors.white54),
                    prefixIcon: const Icon(Icons.image_rounded, color: Colors.white54),
                    enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: const BorderSide(color: Colors.white24)),
                    focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: const BorderSide(color: MayaTheme.neonCyan)),
                    filled: true,
                    fillColor: MayaTheme.slate800,
                  ),
                ),
                const SizedBox(height: 24),
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton.icon(
                    onPressed: _isProcessing ? null : _ocr,
                    icon: _isProcessing
                        ? const SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2, valueColor: AlwaysStoppedAnimation(Colors.white)))
                        : const Icon(Icons.text_fields_rounded),
                    label: Text(_isProcessing ? 'Processing...' : 'Extract Text'),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: MayaTheme.neonCyan,
                      foregroundColor: Colors.black,
                      padding: const EdgeInsets.symmetric(vertical: 14),
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
                    ),
                  ),
                ),
              ],
            ),
          ),
          if (_isProcessing) ...[
            const SizedBox(height: 24),
            const Center(child: CircularProgressIndicator(valueColor: AlwaysStoppedAnimation(MayaTheme.neonCyan))),
          ],
          if (_error != null) ...[
            const SizedBox(height: 24),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(color: MayaTheme.error.withValues(alpha: 0.1), borderRadius: BorderRadius.circular(8), border: Border.all(color: MayaTheme.error)),
              child: Text(_error!, style: MayaTheme.bodyMedium.copyWith(color: MayaTheme.error)),
            ),
          ],
          const SizedBox(height: 24),
          if (_lastResult != null) ...[
            const Text('Extracted Text', style: MayaTheme.titleLarge),
            const SizedBox(height: 12),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(color: MayaTheme.slate800, borderRadius: BorderRadius.circular(8), border: Border.all(color: Colors.white12)),
              child: SelectableText(_lastResult!.text.isNotEmpty ? _lastResult!.text.toString() : 'No text detected', style: MayaTheme.bodyMedium.copyWith(fontFamily: 'monospace')),
            ),
            const SizedBox(height: 16),
            Row(
              children: [
                Expanded(child: _OCRStatCard(label: 'Confidence', value: '${(_lastResult!.confidence * 100).toStringAsFixed(1)}%', color: MayaTheme.neonEmerald)),
                const SizedBox(width: 12),
                Expanded(child: _OCRStatCard(label: 'Status', value: _lastResult!.text.isNotEmpty ? 'Success' : 'No Text', color: _lastResult!.text.isNotEmpty ? MayaTheme.neonEmerald : MayaTheme.neonOrange)),
              ],
            ),
          ],
        ],
      ),
    );
  }
}

class _OCRStatCard extends StatelessWidget {
  final String label;
  final String value;
  final Color color;
  const _OCRStatCard({required this.label, required this.value, required this.color});

  @override
  Widget build(BuildContext context) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.all(16),
        decoration: MayaTheme.glassCardGlow(glowColor: color),
        child: Column(
          children: [
            Icon(Icons.text_fields_rounded, color: color, size: 28),
            const SizedBox(height: 8),
            Text(value, style: MayaTheme.headlineMedium.copyWith(color: color)),
            const SizedBox(height: 4),
            Text(label, style: MayaTheme.labelSmall.copyWith(color: Colors.white54)),
          ],
        ),
      ),
    );
  }
}
